class SelectGroup @JvmOverloads constructor(
    ctx: Context, attrs: AttributeSet? = null
) : LinearLayout(ctx, attrs) {
    private var selected = -1
    fun select(index: Int) {                       // parent enforces one-of-N
        (getChildAt(selected) as? Checkable)?.isChecked = false
        selected = index
        (getChildAt(index) as? Checkable)?.isChecked = true
    }
}
